// Strength knobs measured by calibration (tools/calibrate): per character, the Elo given to Maia, a factor on
// its sampling temperature and its share of random moves. Characters not listed use their starting values.
// Regenerated by `npm run calibrate -- --write`; edit by hand only to try something.
export interface Knobs {
  engineElo?: number;
  tempScale?: number;
  blunderPct?: number;
}

export const CALIBRATION: Record<string, Knobs> = {};
